const categories=['All projects','Design','Developer tools','Productivity','Business','Finance','Education','AI & machine learning','Other'];
let state={view:'discover',source:'curated',provider:'all',technology:'All technologies',category:'All projects',query:'',page:1,loading:false};
let discovered=[], catalog=[], searchToken=0, timer, toastTimer;
let session=null, visibleLimit=48, checkedCandidates=0, discoveryWarning='';
const D=RepoDiscovery;const S=RepoStore;const P=RepoProviders;
let ribbonModes={},detailImage=0;
const demoCache=readStore('reposhelf.demos.v3',{});
function readStore(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let collection=readStore('reposhelf.collection.v1',{});if(!collection||typeof collection!=='object'||Array.isArray(collection))collection={};
let username=readStore('reposhelf.username.v1','');
function persist(){try{localStorage.setItem('reposhelf.collection.v1',JSON.stringify(collection));localStorage.setItem('reposhelf.username.v1',JSON.stringify(username))}catch{toast('Browser storage is unavailable; changes last for this session.')}}
function escape(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function safeUrl(s){try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:null}catch{return null}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000)}
function stars(n){return typeof n==='number'?(n>=1000?(n/1000).toFixed(n>=10000?0:1)+'k':String(n)):'—'}
function repoData(full){return discovered.find(r=>r.full===full)||catalog.find(r=>r.full===full)||curated.find(r=>r.full===full)||collection[full]?.repo}
function cover(r){const preview=S.images(r)[0];return `${preview?`<img class="project-preview" src="${escape(preview.src)}" alt="${escape(r.name)} ${preview.kind==='demo'?'demo screenshot':'project image'}" loading="lazy" decoding="async">`:''}`+ `<div class="cover-inner"><span class="cover-logo">${escape(r.symbol||r.name.slice(0,1).toUpperCase())}</span><span class="cover-title">${escape(r.name)}</span></div><span class="cover-kicker">${escape(r.category)}</span>${r.demo?'<span class="live-badge">Live demo</span>':''}${collection[r.full]?`<span class="fork-badge">${collection[r.full].verified?'Fork verified':'Tracked'}</span>`:''}`}
function coverStyle(r){return `--cover:${/^#[0-9a-f]{3,8}$/i.test(r.color)?r.color:'#25392f'};--ink:${/^#[0-9a-f]{3,8}$/i.test(r.ink)?r.ink:'#d1e5c5'}`}
function card(r){const growth=P.isSpace(r)?null:S.trend(r);const action=P.action(r);return `<article class="card"><button class="cover" style="${coverStyle(r)}" data-details="${escape(r.full)}" aria-label="View ${escape(r.name)} details">${cover(r)}</button><div class="card-heading"><h3><button data-details="${escape(r.full)}">${escape(r.name)}</button></h3></div><p class="repo-owner">${escape(P.isSpace(r)?r.spaceId:r.full)} · ${P.isSpace(r)?'Hugging Face':'GitHub'}</p><p class="card-description">${escape(r.description)}</p><div class="tech-tags">${S.technologies(r).slice(0,3).map(t=>`<button data-tech="${escape(t)}">${escape(t)}</button>`).join('')}</div><div class="card-bottom">${P.isSpace(r)?`<span title="Hugging Face likes">♡ ${stars(r.likes)}</span>`:`<span title="GitHub stars">☆ ${stars(r.stars)}</span><span title="GitHub forks">⑂ ${stars(r.forks)}</span>`}${growth?.score>0?`<span class="growth" title="Growth over ${Math.round(growth.days)} days">+${stars(growth.stars)} stars</span>`:''}<button class="fork-button" data-details="${escape(r.full)}">Details</button></div><div class="card-actions">${r.demo&&D.isAvailable(r)?`<a href="${escape(safeUrl(r.demo))}" target="_blank" rel="noopener">Try demo ↗</a>`:'<span>No confirmed demo</span>'}${D.isAvailable(r)?`<a class="card-fork" href="${escape(action.url)}" target="_blank" rel="noopener" title="${escape(action.label)}">${escape(action.short)}</a>${P.isSpace(r)&&P.githubFull(r)?`<a href="https://github.com/${escape(P.githubFull(r))}/fork" target="_blank" rel="noopener">⑂ Fork</a>`:''}`:`<button data-details="${escape(r.full)}">View tracking</button>`}</div></article>`}
function matching(repos,{category=state.category,query=true}={}){const words=state.query.toLowerCase().trim().split(/\s+/).filter(Boolean);return repos.filter(r=>(state.view==='collection'||D.isAvailable(r))&&P.matchesSource(r,state.provider)&&(!$('#github-only').checked||P.githubFull(r))&&(!$('#demos').checked||r.demo)&&(category==='All projects'||r.category===category)&&(state.technology==='All technologies'||S.technologies(r).includes(state.technology))&&(!query||r.externalQuery===state.query&&state.remote||words.every(q=>[r.full,r.name,r.description,r.language,...S.technologies(r),(r.topics||[]).join(' ')].some(t=>String(t||'').toLowerCase().includes(q)))))}
function order(repos,sort=$('#sort').value){if(['popular','featured','trending'].includes(sort))return sort==='trending'?S.sorted(repos.filter(r=>!P.isSpace(r)),'trending'):P.popular(repos);const list=[...repos];if(sort==='releases')return list.filter(r=>S.recentRelease(r)).sort((a,b)=>Date.parse(b.latestRelease.publishedAt)-Date.parse(a.latestRelease.publishedAt));if(sort==='stars')list.sort((a,b)=>(b.stars??-1)-(a.stars??-1));if(sort==='forks')list.sort((a,b)=>(b.forks??-1)-(a.forks??-1));if(sort==='newest')list.sort((a,b)=>new Date(b.created||0)-new Date(a.created||0));if(sort==='updated')list.sort((a,b)=>new Date(b.updated||0)-new Date(a.updated||0));if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));return list}
function ribbon(title,items,{category='All projects',rank='popular',caption='',controls=false}={}){return `<section class="ribbon"><div class="ribbon-heading"><div><h3>${escape(title)}</h3>${caption?`<p>${escape(caption)}</p>`:''}</div><div class="ribbon-options">${controls?`<button data-ribbon-rank="popular" data-ribbon-category="${escape(category)}" class="${rank==='popular'?'active':''}">Popular</button><button data-ribbon-rank="trending" data-ribbon-category="${escape(category)}" class="${rank==='trending'?'active':''}">Trending</button>`:''}<button class="view-all" data-view-all="${escape(category)}" data-rank="${rank}">View all</button></div></div>${items.length?`<div class="ribbon-track">${items.slice(0,12).map(card).join('')}</div>`:`<p class="ribbon-empty">${rank==='trending'?'Measured trends will appear once we have at least a day of star and fork history.':'No projects match these filters yet.'}</p>`}</section>`}
function renderRibbons(){const pool=matching(catalog);const picks=matching(curated);let html=ribbon('Editor’s picks',picks,{caption:'A small selection chosen for what you can build.',rank:'popular'});html+=ribbon('Popular recent releases',P.popular(pool.filter(r=>S.recentRelease(r))),{caption:'Published GitHub releases from the last 30 days.',rank:'releases'});html+=ribbon('Trending now',S.sorted(pool.filter(r=>!P.isSpace(r)),'trending'),{caption:'Measured growth in stars and forks. Each card shows its observation window.',rank:'trending'});for(const category of categories.slice(1)){if(state.category!=='All projects'&&category!==state.category)continue;const available=pool.filter(r=>r.category===category);if(!available.length)continue;const rank=ribbonModes[category]||'popular';html+=ribbon(category,rank==='trending'?S.sorted(available.filter(r=>!P.isSpace(r)),rank):P.popular(available),{category,rank,controls:true,caption:rank==='popular'?'Popularity within each source: GitHub stars and forks, or Space likes.':'Ranked by measured growth.'})}$('#ribbons').innerHTML=html}
function render(){
$('#fork-count').textContent=Object.keys(collection).length;
$('#section-heading').textContent=state.view==='collection'?'Your collection':state.source==='curated'?'Discover something worth building':'Explore the open-source catalog';
$('#section-caption').textContent=state.view==='collection'?'A starting point for what you’ll build next.':'Good ideas deserve a head start.';
$('.intro').hidden=state.view==='collection';$('.source-control').hidden=state.view==='collection';$('#channels').hidden=state.view==='collection';
document.querySelectorAll('.nav').forEach(b=>{b.classList.toggle('active',b.dataset.view===state.view);b.setAttribute('aria-current',b.dataset.view===state.view?'page':'false')});
$('#curated').classList.toggle('active',state.source==='curated');$('#github').classList.toggle('active',state.source==='github');
$('.categories').innerHTML=categories.map(c=>`<button class="category ${state.category===c?'active':''}" data-category="${c}" aria-pressed="${state.category===c}">${c}</button>`).join('');
$('#channels').innerHTML=S.channels.map(t=>`<button class="channel ${state.technology===t?'active':''}" data-tech="${escape(t)}" aria-pressed="${state.technology===t}"><span>${t==='All technologies'?'◈':escape(t==='Three.js'?'3D':t==='Node.js'?'N':t.slice(0,2))}</span>${escape(t)}</button>`).join('');
const storefront=state.view==='discover'&&state.source==='curated'&&!state.query;
let repos=order(matching(state.view==='collection'?Object.values(collection).map(x=>x.repo).filter(Boolean):state.source==='curated'?catalog:discovered));
$('#ribbons').hidden=!storefront;$('#grid').hidden=storefront;if(storefront)renderRibbons();
$('#result-count').textContent=`${repos.length.toLocaleString()} project${repos.length===1?'':'s'}${$('#demos').checked?' with live demos':''}`;
$('#data-note').textContent=state.view==='collection'?'Saved in this browser':`${catalog.filter(D.isAvailable).length.toLocaleString()} indexed${checkedCandidates?' · '+checkedCandidates.toLocaleString()+' checked live':''}`;
$('#grid').innerHTML=repos.slice(0,visibleLimit).map(card).join('')||`<div class="empty"><h3>${state.loading?'Finding your next project…':state.view==='collection'&&!Object.keys(collection).length?'Your next project starts here.':'No projects found'}</h3><p>${state.loading?'Checking repository README files for live demo links.':state.view==='collection'&&!Object.keys(collection).length?'Explore a project, fork it on GitHub, then add it here. You can also sync your public forks with your GitHub username.':$('#sort').value==='trending'?'Trending requires measured star and fork growth. Choose Popular while history accumulates.':'Try a different search or technology, or switch off “Live demos only”.'}</p>${!state.loading?'<button class="button outline" id="reset-filters">Reset filters</button>':''}</div>`;
const moreLocal=repos.length>visibleLimit;$('#search-external').hidden=storefront||state.view==='collection'||state.provider==='huggingface';$('#search-external').disabled=state.loading;$('#search-external').textContent=state.loading?'Checking GitHub…':state.remote&&hasMore()?'Find more on GitHub':'Search beyond the catalog on GitHub';
$('#load-more').hidden=storefront||!moreLocal;$('#load-more').disabled=false;$('#load-more').textContent='Show more projects';
$('#account-button span:last-child').textContent=username?`@${username}`:'GitHub account';
}
function showDetails(full){const r=repoData(full);if(!r)return;const entry=collection[full],url=P.repositoryUrl(r),action=P.action(r),images=S.images(r),growth=P.isSpace(r)?null:S.trend(r);detailImage=Math.min(detailImage,Math.max(0,images.length-1));const image=images[detailImage];
$('#detail-content').innerHTML=`<p class="eyebrow">${escape(r.category)} · ${D.isAvailable(r)?P.isSpace(r)?'HUGGING FACE SPACE':'PUBLIC GITHUB REPOSITORY':'UNAVAILABLE'}</p><div class="detail-gallery">${image?`<img class="detail-preview" src="${escape(image.src)}" alt="${escape(r.name)} ${image.kind==='demo'?'demo screenshot':'project image'}"><p class="preview-caption">${image.kind==='demo'?'Captured from the live demo':'Project image from the README'}${image.capturedAt?' · '+escape(new Date(image.capturedAt).toLocaleDateString()):''}</p>`:`<div class="cover" style="${coverStyle(r)}">${cover(r)}</div><p class="preview-caption">A screenshot is not available for this project yet.</p>`}${images.length>1?`<div class="gallery-thumbs">${images.map((i,n)=>`<button data-gallery="${n}" data-repo="${escape(full)}" class="${n===detailImage?'active':''}" aria-label="Show image ${n+1}"><img src="${escape(i.src)}" alt="Preview ${n+1}" loading="lazy"></button>`).join('')}</div>`:''}</div><h2>${escape(r.name)}</h2><p class="repo-owner">${escape(r.full)}</p><p>${escape(r.description)}</p><div class="tech-tags detail-tags">${S.technologies(r).map(t=>`<button data-tech="${escape(t)}">${escape(t)}</button>`).join('')}${r.language?`<span>${escape(r.language)}</span>`:''}</div><div class="detail-actions">${r.demo&&D.isAvailable(r)?`<a class="button lime" href="${escape(safeUrl(r.demo))}" target="_blank" rel="noopener">Try demo ↗</a>`:''}${D.isAvailable(r)?`<a class="button outline" href="${escape(action.url)}" target="_blank" rel="noopener">${escape(action.label)}</a>`:''}${P.isSpace(r)&&P.githubFull(r)?`<a class="button outline" href="https://github.com/${escape(P.githubFull(r))}/fork" target="_blank" rel="noopener">Fork source on GitHub</a>`:''}<a class="button outline" href="${url}" target="_blank" rel="noopener">Repository</a></div><dl class="project-facts">${P.isSpace(r)?`<div><dt>Space likes</dt><dd>${stars(r.likes)}</dd></div><div><dt>Runtime</dt><dd>${escape(r.runtime)}</dd></div>`:`<div><dt>Stars</dt><dd>${stars(r.stars)}</dd></div><div><dt>Forks</dt><dd>${stars(r.forks)}</dd></div>`}<div><dt>License</dt><dd>${escape(r.license||'Not specified')}</dd></div><div><dt>Latest release</dt><dd>${r.latestRelease?`<a href="${escape(safeUrl(r.latestRelease.url)||url)}" target="_blank" rel="noopener">${escape(r.latestRelease.tag||r.latestRelease.name)}</a><small>${escape(new Date(r.latestRelease.publishedAt).toLocaleDateString())}</small>`:r.releaseCheckedAt?'No published release':'Not checked yet'}</dd></div><div><dt>Last code update</dt><dd>${r.updated?escape(new Date(r.updated).toLocaleDateString()):'Not available'}</dd></div><div><dt>Availability check</dt><dd>${r.lastCheckedAt?escape(new Date(r.lastCheckedAt).toLocaleDateString()):'Not checked yet'}${r.checkError?'<small>Latest attempt will be retried</small>':''}</dd></div></dl>${growth?`<p class="growth-detail">+${stars(growth.stars)} stars · +${stars(growth.forks)} forks over ${Math.round(growth.days)} days</p>`:''}<p class="small">${r.demo?'Demo links are published by the project. Availability checks confirm repository access, not demo uptime.':'No confirmed live demo.'} Check the license before reusing code.</p>${r.spaces?.length?`<p class="small">Also on Hugging Face: ${r.spaces.map(x=>`<a href="${escape(x.url)}" target="_blank" rel="noopener">${escape(x.id)}</a>`).join(', ')}</p>`:''}${r.discoveredVia?.length?`<p class="small">Discovered via ${r.discoveredVia.map(x=>`<a href="${escape(safeUrl(x.url))}" target="_blank" rel="noopener">${escape(x.name)}</a>`).join(', ')}. Demo checked independently.</p>`:''}<div class="tracking"><p>${entry?(entry.verified?`Public fork verified in @${escape(username)}.`:'Tracked manually in this browser; not yet verified.'): P.isSpace(r)?'Duplicate on Hugging Face using your Hugging Face account, then save it here. Saved Spaces are tracked manually.':'Fork on GitHub, then track it here or sync your public account.'}</p><button class="button ${entry?'outline':'lime'}" id="track-repo">${entry?'Remove tracking':P.isSpace(r)?'Save this Space':'Track this fork'}</button></div>${entry?.url?`<p><a href="${escape(safeUrl(entry.url)||url)}" target="_blank" rel="noopener">Open my fork ↗</a></p>`:''}`;
$('#track-repo').onclick=()=>{if(collection[full]){delete collection[full];toast('Removed from your collection')}else{collection[full]={repo:r,verified:false,added:new Date().toISOString()};toast(P.isSpace(r)?'Space saved in this browser.':'Tracking saved. Sync your GitHub account to verify it.')}persist();render();showDetails(full)};if(!$('#detail').open)$('#detail').showModal()}
async function api(path){const res=await fetch(`https://api.github.com${path}`,{headers:{Accept:'application/vnd.github+json'},signal:AbortSignal.timeout(12000)});if(!res.ok){if(res.status===403||res.status===429)throw new Error('GitHub’s public API limit was reached.');if(res.status===404)throw new Error('GitHub could not find that public account or repository.');throw new Error(`GitHub is unavailable (${res.status}). Please try again.`)}return res.json()}
async function pool(items,fn,limit=4){let i=0;return Promise.all(Array.from({length:Math.min(limit,items.length)},async()=>{while(i<items.length){const n=i++;await fn(items[n],n)}}))}
async function hydrate(){let loaded=0;try{await pool(curated,async r=>{try{const d=await api(`/repos/${r.full}`);Object.assign(r,{stars:d.stargazers_count,forks:d.forks_count,created:d.created_at,updated:d.pushed_at,license:d.license?.spdx_id==='NOASSERTION'?null:d.license?.spdx_id});loaded++;if(collection[r.full])collection[r.full].repo=r}catch{}});render();if(!loaded&&state.source==='curated'&&state.view==='discover')$('#status').textContent='Live GitHub statistics are unavailable. You can still browse projects, open demos, and track forks.'}catch{}}
function classify(r){return D.classify(r)}
async function findDemo(repo){const key=repo.full.toLowerCase(),cached=demoCache[key];if(cached&&cached.updated===repo.updated&&Date.now()-cached.checked<7*86400000)return cached.demo;
let content=null;for(const path of ['README.md','readme.md','README.MD']){try{const res=await fetch(`https://raw.githubusercontent.com/${repo.full}/${encodeURIComponent(repo.branch||'main')}/${path}`,{signal:AbortSignal.timeout(7000)});if(res.status===404)continue;if(!res.ok)throw new Error('README temporarily unavailable');content=await res.text();break}catch{return undefined}}
const demo=D.extractDemo(content,repo.homepage);demoCache[key]={updated:repo.updated,checked:Date.now(),demo};return demo;}
function saveDemoCache(){try{const recent=Object.entries(demoCache).sort((a,b)=>b[1].checked-a[1].checked).slice(0,3000);localStorage.setItem('reposhelf.demos.v3',JSON.stringify(Object.fromEntries(recent)))}catch{}}
function hasMore(){return Boolean(session?.queries.some(q=>!q.done))}
function mergeRepos(items){const repos=new Map(discovered.map(r=>[r.full.toLowerCase(),r]));for(const r of items)repos.set(r.full.toLowerCase(),r);discovered=[...repos.values()]}
function useCatalog(){searchToken++;state.loading=false;state.remote=false;session=null;visibleLimit=48;checkedCandidates=0;discovered=[...catalog];$('#status').textContent='';render()}
async function loadCatalog(){const read=async path=>{const res=await fetch(path,{signal:AbortSignal.timeout(10000)});if(!res.ok)throw Error('Catalog unavailable');return res.json()};const results=await Promise.allSettled([read('catalog.json'),read('spaces.json')]);const data=results[0].status==='fulfilled'?results[0].value:{repositories:[]};const spaces=results[1].status==='fulfilled'?results[1].value:{repositories:[]};const all=new Map(curated.map(r=>[r.full.toLowerCase(),r]));for(const r of data.repositories||[])if(P.validId(r.full)&&typeof r.name==='string'&&(!r.demo||D.demoUrl(r.demo)))all.set(r.full.toLowerCase(),r);for(const r of curated){const saved=all.get(r.full.toLowerCase());if(saved)Object.assign(r,saved)}catalog=P.mergeCatalog([...all.values()],(spaces.repositories||[]).filter(r=>P.isSpace(r)&&P.validId(r.spaceId)&&r.full===`hf:${r.spaceId}`&&typeof r.name==='string'&&(!r.demo||r.demo===P.repositoryUrl(r)))).map(r=>({...r,technologies:S.technologies(r)}));useCatalog();if(results[0].status==='rejected')$('#status').textContent='The saved catalog is temporarily unavailable. Editor’s picks are still available.'}
async function discover(append=false){const token=++searchToken;if(!append){state.remote=true;visibleLimit=48;checkedCandidates=0;discoveryWarning='';session={queries:D.searchQueries({query:state.query,category:state.category,technology:state.technology,demos:$('#demos').checked,newest:$('#sort').value==='newest'}).map(q=>({q,page:1,done:false})),next:0};discovered=[...catalog]}
state.loading=true;$('#status').textContent='Searching GitHub and checking demo links…';render();let temporaryFailures=0;
try{for(let batch=0;batch<3&&hasMore();batch++){if(token!==searchToken)return;let task;for(let i=0;i<session.queries.length;i++){const index=session.next++%session.queries.length;if(!session.queries[index].done){task=session.queries[index];break}}if(!task)break;
const sort=$('#sort').value==='updated'?'updated':$('#sort').value==='forks'?'forks':'stars';const data=await api(`/search/repositories?q=${encodeURIComponent(task.q)}&sort=${sort}&order=desc&per_page=100&page=${task.page}`);if(token!==searchToken)return;task.page++;task.done=data.items.length<100||(task.page-1)*100>=Math.min(data.total_count??1000,1000);
const existing=new Map([...catalog,...discovered].map(r=>[r.full.toLowerCase(),r]));const results=data.items.map(d=>({...D.mapRepo(d),externalQuery:state.query}));await pool(results,async r=>{if(token!==searchToken)return;const known=existing.get(r.full.toLowerCase());if(known?.demo&&D.isAvailable(known))Object.assign(r,{demo:known.demo,name:known.name,color:known.color,ink:known.ink,symbol:known.symbol,screenshots:known.screenshots,latestRelease:known.latestRelease,releaseCheckedAt:known.releaseCheckedAt,technologies:known.technologies,metrics:known.metrics,lastCheckedAt:known.lastCheckedAt});else{const demo=await findDemo(r);if(demo===undefined)temporaryFailures++;else r.demo=demo;}if(token!==searchToken)return;checkedCandidates++;mergeRepos([r]);if(checkedCandidates%8===0)render()},8);if(token!==searchToken)return;saveDemoCache();render();const matches=matching(discovered);if(matches.length>=24)break;}
if(token!==searchToken)return;$('#status').textContent=`Checked ${checkedCandidates.toLocaleString()} repositories for demo links.${temporaryFailures?' Some READMEs could not be reached; they have not been marked as having no demo.':''}${hasMore()?' Keep exploring to search additional batches.':' All results in this search have been checked.'}${$('#sort').value==='newest'?' Newest live search covers the last 30 days; creation-date sorting applies to loaded results.':''}`;
}catch(e){if(token!==searchToken)return;discoveryWarning=e.message||'Could not reach GitHub.';$('#status').textContent=`${discoveryWarning} Your catalog matches are still shown. Retry with the GitHub search button later.`}finally{if(token===searchToken){state.loading=false;render()}}}
async function syncForks(){const output=$('#sync-status');output.textContent='Checking your public GitHub forks…';let count=0,scanned=0;try{await api(`/users/${username}`);let forks=[];for(let page=1;page<=10;page++){const repos=await api(`/users/${username}/repos?type=owner&sort=updated&per_page=100&page=${page}`);scanned+=repos.length;forks.push(...repos.filter(r=>r.fork));if(repos.length<100)break}let failures=0;await pool(forks,async f=>{try{const d=await api(`/repos/${f.full_name}`);if(!d.parent)return;const full=d.parent.full_name;const existing=repoData(full);const r=existing||{full,name:d.parent.name,description:d.parent.description||'A public repository in your fork collection.',category:classify(d.parent),language:d.parent.language,stars:d.parent.stargazers_count,updated:d.parent.pushed_at,demo:null,color:'#25392f',ink:'#d1e5c5'};collection[full]={repo:r,verified:true,url:f.html_url,added:collection[full]?.added||new Date().toISOString()};count++}catch{failures++}});persist();render();output.textContent=`Verified ${count} public fork${count===1?'':'s'} for @${username}.${failures?' Some forks could not be checked; try syncing again later.':''}${scanned===1000?' Checked the 1,000 most recently updated repositories.':''} Private forks are not accessible.`;toast('Your collection has been updated')}catch(e){output.textContent=e.message||'Could not reach GitHub. Try again later.'}}
$('#account-button').onclick=()=>{$('#username').value=username;$('#sync-status').textContent='';$('#account').showModal()};
$('#account-form').onsubmit=e=>{e.preventDefault();const next=$('#username').value.trim();if(!/^[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,37}[a-zA-Z0-9])?$/.test(next)){$('#sync-status').textContent='Enter a valid GitHub username.';return}if(username.toLowerCase()!==next.toLowerCase()){Object.values(collection).forEach(e=>{e.verified=false;delete e.url})}username=next;persist();render();syncForks()};
document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
document.addEventListener('click',e=>{const details=e.target.closest('[data-details]');if(details){detailImage=0;showDetails(details.dataset.details)}const tech=e.target.closest('[data-tech]');if(tech){state.technology=tech.dataset.tech;$('#detail').close();if(state.source==='github')useCatalog();else render()}const rank=e.target.closest('[data-ribbon-rank]');if(rank){ribbonModes[rank.dataset.ribbonCategory]=rank.dataset.ribbonRank;render()}const all=e.target.closest('[data-view-all]');if(all){state.source='github';state.category=all.dataset.viewAll;$('#sort').value=all.dataset.rank;useCatalog()}const gallery=e.target.closest('[data-gallery]');if(gallery){detailImage=Number(gallery.dataset.gallery);showDetails(gallery.dataset.repo)}const cat=e.target.closest('[data-category]');if(cat){state.category=cat.dataset.category;if(state.source==='github'&&state.view==='discover')useCatalog();else render()}const nav=e.target.closest('[data-view]');if(nav){state.view=nav.dataset.view;if(state.view==='collection'){searchToken++;state.loading=false}$('#status').textContent='';render()}if(e.target.closest('#reset-filters')){state.category='All projects';state.technology='All technologies';state.query='';$('#search').value='';$('#demos').checked=false;render();if(state.source==='github'&&state.view==='discover')useCatalog()}});

$('#curated').onclick=()=>{state.source='curated';state.query='';$('#search').value='';visibleLimit=48;searchToken++;state.loading=false;$('#status').textContent='';render()};$('#github').onclick=()=>{state.source='github';useCatalog()};
$('#search').oninput=e=>{state.query=e.target.value;if(state.query)state.source='github';useCatalog()};
$('#demos').onchange=()=>useCatalog();$('#provider').onchange=e=>{state.provider=e.target.value;useCatalog()};$('#github-only').onchange=()=>useCatalog();$('#sort').onchange=()=>useCatalog();$('#load-more').onclick=()=>{visibleLimit+=48;render()};$('#search-external').onclick=()=>discover(Boolean(state.remote&&hasMore()));
document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();$('#search').focus()}});
render();loadCatalog();

document.addEventListener('error',e=>{if(e.target.matches?.('.project-preview'))e.target.remove();else if(e.target.matches?.('.detail-preview')){e.target.hidden=true;toast('This preview image is temporarily unavailable.')}},true);
